func decomposeCall(ctx *planner.Context, call atom.Atom, requireTopLevel bool) (atom.Atom, planner.DecompositionStatus) {
	empty := atom.EmptyList()
	if ctx == nil || ctx.Execution == nil || ctx.Prepared == nil {
		return empty, planner.InvalidContext
	}
	ex := ctx.Execution
	ex.ResetDiagnostics()
	if ctx.WorldState == nil || ctx.Bindings == nil {
		return empty, planner.InvalidContext
	}
	if !call.Is(atom.KindList) || call.Len() < 1 {
		return empty, planner.InvalidCall
	}
	head, _ := call.At(0)
	if !head.Is(atom.KindSymbol) {
		return empty, planner.InvalidCall
	}
	argumentCount := call.Len() - 1
	_ = argumentCount
	ex.Begin(ctx, factSymbols, callNames)
	entry := -1
	if entry < 0 && head.Symbol() == sym11 && argumentCount == 0 {
		entry = 18
	}
	if entry < 0 && head.Symbol() == sym11 && argumentCount == 1 {
		entry = 19
	}
	if entry < 0 && head.Symbol() == sym12 && argumentCount == 0 {
		entry = 22
	}
	if entry < 0 && head.Symbol() == sym12 && argumentCount == 1 {
		entry = 23
	}
	if entry < 0 && head.Symbol() == sym13 && argumentCount == 0 {
		if requireTopLevel {
			return empty, planner.InvalidCall
		}
		entry = 24
	}
	if entry < 0 && head.Symbol() == sym13 && argumentCount == 1 {
		if requireTopLevel {
			return empty, planner.InvalidCall
		}
		entry = 25
	}
	if entry < 0 && head.Symbol() == sym14 && argumentCount == 0 {
		if requireTopLevel {
			return empty, planner.InvalidCall
		}
		entry = 26
	}
	if entry < 0 && head.Symbol() == sym14 && argumentCount == 1 {
		entry = 27
	}
	if entry < 0 && head.Symbol() == sym15 && argumentCount == 0 {
		entry = 28
	}
	if entry < 0 {
		return empty, planner.InvalidCall
	}
	ex.DebugBeginPlan(&definition, uint32(entry))
	result := 0
	switch entry {
	case 18:
		result = ex.Run(method18)
	case 19:
		if argument, _ := call.At(1); !argument.IsBound() {
			return empty, planner.InvalidCall
		} else {
			ex.V[0] = argument
		}
		result = ex.Run(method19)
	case 22:
		result = ex.Run(method22)
	case 23:
		if argument, _ := call.At(1); !argument.IsBound() {
			return empty, planner.InvalidCall
		} else {
			ex.V[0] = argument
		}
		result = ex.Run(method23)
	case 24:
		result = ex.Run(method24)
	case 25:
		if argument, _ := call.At(1); !argument.IsBound() {
			return empty, planner.InvalidCall
		} else {
			ex.V[0] = argument
		}
		result = ex.Run(method25)
	case 26:
		result = ex.Run(method26)
	case 27:
		if argument, _ := call.At(1); !argument.IsBound() {
			return empty, planner.InvalidCall
		} else {
			ex.V[0] = argument
		}
		result = ex.Run(method27)
	case 28:
		result = ex.Run(method28)
	}
	if result == 0 {
		ex.DebugEndPlan(&definition, false)
		return empty, ex.FailureState
	}
	for ex.PendingCount() != 0 {
		next := ex.PopPending()
		if next == nil {
			break
		}
		if ex.Run(next) == 0 {
			ex.DebugEndPlan(&definition, false)
			return empty, ex.FailureState
		}
	}
	ex.DebugEndPlan(&definition, true)
	return ex.PlanAtom(), planner.Succeeded
}
